import{_ as t}from"./chunks/hiwonder_ackermann.bMhWmXdo.js";import{_ as a}from"./chunks/hiwonder_wiring_annotated.BQltOWsO.js";import{_ as i,a as n,b as s}from"./chunks/hiwonder_ackermann_servo.Db7AyrDT.js";import{_ as l,C as h,o as c,c as d,j as o,a as p,E as m,al as u}from"./chunks/framework.7vp1BMOE.js";const C=JSON.parse('{"title":"Hiwonder Ackermann","description":"","frontmatter":{},"headers":[],"relativePath":"en/complete_vehicles_rover/hiwonder_ackermann.md","filePath":"en/complete_vehicles_rover/hiwonder_ackermann.md"}'),f={name:"en/complete_vehicles_rover/hiwonder_ackermann.md"};function g(w,e,v,b,_,k){const r=h("Badge");return c(),d("div",null,[e[0]||(e[0]=o("h1",{id:"hiwonder-ackermann",tabindex:"-1"},[p("Hiwonder Ackermann "),o("a",{class:"header-anchor",href:"#hiwonder-ackermann","aria-label":'Permalink to "Hiwonder Ackermann"'},"​")],-1)),m(r,{type:"tip",text:"PX4 v1.18"}),e[1]||(e[1]=u('<p>The <a href="https://www.hiwonder.com/products/ackermann-steering-chassis?variant=40382428348503" target="_blank" rel="noreferrer">Hiwonder Ackermann</a> rover is a bare-bones platform including a chassis, four wheels, two <a href="https://www.hiwonder.com/products/hall-encoder-dc-geared-motor?variant=40451123675223" target="_blank" rel="noreferrer">motors with encoders</a>, a servo and a <a href="https://www.hiwonder.com/products/4-channel-encoder-motor-driver" target="_blank" rel="noreferrer">motor driver board</a>. The chassis offers many mounting points, providing the flexibility to attach your own flight controller, sensors and other payload.</p><p>This documentation illustrates the setup of the rover and the configuration of the actuators.</p><p><img src="'+t+'" alt="Hiwonder Ackermann"></p><h2 id="parts-list" tabindex="-1">Parts List <a class="header-anchor" href="#parts-list" aria-label="Permalink to &quot;Parts List&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The hardware below is just an example — use whatever you have available. Make sure all parts are compatible with your flight controller&#39;s ports, and adjust the wiring as needed. Alternatives are listed in:</p><ul><li><a href="./../flight_controller/">Flight Controllers</a></li><li><a href="./../getting_started/rc_transmitter_receiver#compatible_receivers">PX4-Compatible Receivers</a></li><li><a href="./../data_links/">Data Links</a></li><li><a href="./../gps_compass/#supported-gnss">Global Navigation Satellite Systems (GNSS)</a> or <a href="./../gps_compass/rtk_gps">RTK GNSS</a></li></ul></div><p>The following parts are used in this build:</p><ul><li><p>Frame: <a href="https://www.hiwonder.com/products/ackermann-steering-chassis?variant=40382428348503" target="_blank" rel="noreferrer">Hiwonder Ackermann Chassis</a></p></li><li><p>Flight Controller: <a href="https://auterion.com/product/skynode-s/" target="_blank" rel="noreferrer">Auterion Skynode S</a></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The flight controller and motor driver board used in this build are both directly supplied at the same 3S battery voltage (~11V).</p><p>Many flight controllers require a lower voltage power supply, so if you are using a different controller you may need a DC-to-DC converter to power it from the battery — see <a href="./../power_module/">Power Modules &amp; Power Distribution Boards</a>.</p></div></li><li><p>Receiver: <a href="https://www.team-blacksheep.com/products/prod:crossfire_nano_rx?srsltid=AfmBOopvPF1mhPRIS11amSwdKf4OFZlt2ibj7XJwu05kVWt4S_L-ZNuD" target="_blank" rel="noreferrer">TBS Crossfire Nano RX</a></p></li><li><p>Power: 3S Lipo Battery</p></li><li><p>Dc-to-Dc Converter: <a href="https://www.mateksys.com/?portfolio=bec12s-pro" target="_blank" rel="noreferrer">BEC12S-PRO</a>.</p><p>The servo needs to be supplied with 6-8.4V (and with a current rating of higher than 3A). This Dc-to-Dc converted is needed to transform the voltage from the 3S battery to this range.</p></li><li><p>GNSS: <a href="./../gps_compass/rtk_gps_holybro_h-rtk-f9p">Holybro RTK F9P GPS</a></p></li><li><p>I2C Splitter</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This part is only necessary if your flight controller has only one I2C port (we need one for the motor driver board and one for the compass in the GNSS module). Many boards will have a dedicated GPS port (which often includes an I2C port) and one or more separate I2C ports for additional peripherals.</p></div></li><li><p>LTE Dongle: Used to establish a data link between the vehicle and the ground control station.</p></li></ul><h2 id="wiring-and-assembly" tabindex="-1">Wiring and Assembly <a class="header-anchor" href="#wiring-and-assembly" aria-label="Permalink to &quot;Wiring and Assembly&quot;">​</a></h2><p>The following images shows the wiring of the various components of this build. The connections from the motors to the motor controller board are not shown.</p><p><img src="'+a+'" alt="Hiwonder Wiring"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This image only serves as an example for the wiring process, with your hardware this can look very different. Check the documentation of your parts to ensure that you connect to correct pins.</p></div><p>Now connect the battery to the Dc-to-Dc converter to give it power. To power the servo, connect the red (6-8.4V) and black (GND) wire to the output of the DC-to-Dc converter and the white (PWM) wire to a PWM output of your flight controller.</p><p><img src="'+i+'" alt="Hiwonder Ackermann Servo Wiring"></p><p>With the wiring complete, you can now securely attach your hardware to the chassis.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For the initial build you might attach components using double sided tape. For a longer term solution we highly recommend 3d printing mounts that you attach to the chassis using the mounting points.</p></div><h2 id="building-the-firmware" tabindex="-1">Building the Firmware <a class="header-anchor" href="#building-the-firmware" aria-label="Permalink to &quot;Building the Firmware&quot;">​</a></h2><p>This frame works with the usual Rover firmware variants on most flight controllers. You can use either prebuilt versions or build the firmware yourself (see <a href="./../config_rover/#flashing-the-rover-build">Flashing the Rover Build</a> and <a href="./../config_rover/#building-rover">Building Rover</a> in <em>Rover Configuration/Tuning</em>).</p><p>A few boards may omit the <a href="./../modules/modules_driver#hiwonder-emm"><code>hiwonder_emm</code> driver</a> for the <a href="./../peripherals/hiwonder_emm">Hiwonder 4-Channel Encoder Motor Module</a> used by this vehicle. If your board does not ship with it you will need a custom build — see <a href="./../peripherals/hiwonder_emm#building-the-firmware">Hiwonder 4-Channel Encoder Motor Module &gt; Building the Firmware</a> for instructions.</p><h2 id="px4-configuration" tabindex="-1">PX4 Configuration <a class="header-anchor" href="#px4-configuration" aria-label="Permalink to &quot;PX4 Configuration&quot;">​</a></h2><p>Use <em>QGroundControl</em> for rover configuration:</p><ol><li><a href="./../config_rover/#flashing-the-rover-build">Flash the rover build</a> onto your flight controller with the following adjustments:</li><li>In the <a href="./../config/">Basic Configuration</a> section, select the <a href="./../config/airframe">Airframe</a> tab.</li><li>Choose <strong>Hiwonder Ackermann</strong> under the <strong>Rover</strong> category (Alternatively you can set the parameter <code>SYS_AUTOSTART</code> to <code>51003</code>).</li></ol><p>Then configure the actuators:</p><ol><li><p>Navigate to <a href="./../config/actuators">Actuators Configuration &amp; Testing</a> in QGroundControl.</p></li><li><p>Select the Hiwonder EMM driver from the list of <em>Actuator Outputs</em>.</p><p>Assign the two populated channels of the motor controller board to <code>Throttle</code>. The channels are noted on the motor controller board (alternatively randomly assign the channels and use the actuator testing tab to find the correct assignments).</p><p><img src="'+n+'" alt="Motor Setup"></p></li><li><p>Now ensure that both motors are spinning in the same direction. If that is not the case check the <code>Rev Range</code> box on one of the motors.</p></li><li><p>Arm the rover in <a href="./../flight_modes_rover/manual#manual-mode">Manual Mode</a> and use the trottle stick to drive forwards. If the rover drives backwards instead, invert the <code>Rev Range</code> checkboxes on <strong>both</strong> motors.</p></li><li><p>To configure the servo motor, assign the populated PWM channel to <code>Steering</code>. Set the minimum value to <code>800</code>, the maximum to <code>2200</code> and the disarm value to <code>1500</code>.</p><p><img src="'+s+'" alt="Servo Setup"></p></li><li><p>Arm the rover in <a href="./../flight_modes_rover/manual#manual-mode">Manual Mode</a> and use the steering stick to move the servo. If the rover steers in the wrong direction check the <code>Rev Range</code> checkbox of the servo.</p></li></ol><p>You have now successfully setup your rover and can start testing all <a href="./../flight_modes_rover/">driving modes</a> PX4 has to offer!</p>',24))])}const A=l(f,[["render",g]]);export{C as __pageData,A as default};
